function camPos(){return world.camera.position.toArray();}
function frameCheck(t){const f=contest.sample(t);if(bowling)court.userData.view.camera(f,screen.width/screen.height,$('fvCamera').value);else camera(f);world.camera.updateMatrixWorld(true);const v=new T.Vector3();let x=0,top=-9,bot=9;const pts=[];for(const [k,p]of f.players.entries()){if(bowling&&k!==f.roll.side*contest.perSide+f.roll.actor)continue;pts.push([p.x,0,p.z],[p.x,1.9+(p.jump||0),p.z]);}if(f.ball)pts.push([f.ball.x,f.ball.y,f.ball.z]);for(const q of pts){v.set(q[0]+OX,q[1],q[2]).project(world.camera);x=Math.max(x,Math.abs(v.x));top=Math.max(top,v.y);bot=Math.min(bot,v.y);}return{x,top,bot,distance:world.camera.position.distanceTo(new T.Vector3(0,0,0))};}
